{"content": "const fs = require("fs");
const path = require("path");
const vm = require("vm");
const ROOT = "D:/ZZH/aska/github/shunkai-dg";
const compiler = require(path.join(ROOT, "node_modules/vue-template-compiler"));
const babel = require(path.join(ROOT, "node_modules/@babel/parser"));

const views = [
  "src/views/contact/ContactUs.vue",
  "src/views/join/JoinUs.vue",
  "src/views/join/JoinUsDetail.vue",
];

let failed = false;

for (const rel of views) {
  const file = path.join(ROOT, rel);
  const src = fs.readFileSync(file, "utf8");
  const sfc = compiler.parseComponent(src);
  if (!sfc.template) {
    console.log("NO TEMPLATE", rel);
    failed = true;
    continue;
  }
  const out = compiler.compile(sfc.template.content);
  if (out.errors && out.errors.length) {
    failed = true;
    console.log("TEMPLATE ERRORS", rel, out.errors);
  }
  try {
    babel.parse(sfc.script.content, { sourceType: "module" });
  } catch (e) {
    failed = true;
    console.log("SCRIPT PARSE ERROR", rel, e.message);
  }
  console.log("SFC OK", rel, "| template errors:", (out.errors || []).length);
}

function loadLocale(rel) {
  const code = fs
    .readFileSync(path.join(ROOT, rel), "utf8")
    .replace(/export\s+default/, "module.exports =");
  const sandbox = { module: { exports: {} }, exports: {} };
  vm.createContext(sandbox);
  vm.runInContext(code, sandbox, { filename: rel });
  return sandbox.module.exports;
}

function keys(obj, prefix) {
  let out = [];
  for (const k of Object.keys(obj)) {
    const p = prefix ? prefix + "." + k : k;
    const v = obj[k];
    if (v && typeof v === "object" && !Array.isArray(v)) out = out.concat(keys(v, p));
    else out.push(p);
  }
  return out;
}

for (const ns of ["contact", "join"]) {
  const zh = loadLocale("src/i18n/lang/zh-CN/" + ns + ".js");
  const en = loadLocale("src/i18n/lang/en-US/" + ns + ".js");
  const kz = keys(zh, "").sort();
  const ke = keys(en, "").sort();
  const onlyZh = kz.filter((k) => ke.indexOf(k) === -1);
  const onlyEn = ke.filter((k) => kz.indexOf(k) === -1);
  console.log("NS", ns, "| zh keys:", kz.length, "en keys:", ke.length, "| onlyZh:", JSON.stringify(onlyZh), "| onlyEn:", JSON.stringify(onlyEn));
  if (onlyZh.length || onlyEn.length) failed = true;
  // 空值检查
  const empty = kz.concat(ke).filter((k) => {
    const get = (o) => k.split(".").reduce((a, c) => (a ? a[c] : undefined), o);
    return !get(zh) || !get(en);
  });
  if (empty.length) {
    failed = true;
    console.log("EMPTY VALUES", ns, JSON.stringify(empty));
  }
}

console.log(failed ? "RESULT: FAILED" : "RESULT: ALL CHECKS PASSED");
