const path = require("path");
const vm = require("vm");
const ROOT = "D:/ZZH/aska/github/shunkai-dg";
const Vue = require(path.join(ROOT, "node_modules/vue"));
const VueI18n = require(path.join(ROOT, "node_modules/vue-i18n"));
Vue.use(VueI18n);

function loadLocale(rel) {
  const code = fs
    .readFileSync(path.join(ROOT, rel), "utf8")
    .replace(/export\s+default/, "module.exports =");
  const sandbox = { module: { exports: {} }, exports: {} };
  vm.createContext(sandbox);
  vm.runInContext(code, sandbox, { filename: rel });
  return sandbox.module.exports;
}

const mk = (loc) => ({
  common: loadLocale(`src/i18n/lang/${loc}/common.js`),
  contact: loadLocale(`src/i18n/lang/${loc}/contact.js`),
  join: loadLocale(`src/i18n/lang/${loc}/join.js`),
});

const messages = { "zh-CN": mk("zh-CN"), "en-US": mk("en-US") };
const i18n = new VueI18n({ locale: "en-US", fallbackLocale: "en-US", messages, silentTranslationWarn: false });

function keys(obj, prefix) {
  let out = [];
  for (const k of Object.keys(obj)) {
    const p = prefix ? prefix + "." + k : k;
    const v = obj[k];
    if (v && typeof v === "object" && !Array.isArray(v)) out = out.concat(keys(v, p));
    else out.push(p);
  }
  return out;
}

let failed = false;
for (const loc of ["zh-CN", "en-US"]) {
  i18n.locale = loc;
  for (const ns of ["contact", "join"]) {
    for (const k of keys(messages[loc][ns], ns)) {
      const expected = k.split(".").reduce((a, c) => a[c], messages[loc]);
      const got = i18n.t(k);
      if (got !== expected) {
        failed = true;
        console.log("MISMATCH", loc, k, "\n  expected:", JSON.stringify(expected), "\n  got     :", JSON.stringify(got));
      } else {
        console.log("t() ok ", loc.padEnd(6), k, "=>", JSON.stringify(got).slice(0, 70));
      }
    }
  }
}
console.log(failed ? "RESULT: FAILED" : "RESULT: vue-i18n RENDERS ALL MESSAGES EXACTLY AS DECLARED");
